contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, string calldata description) public {
        // precondition: caller is not an admin (admin status is fixed for this deployment)
        require(!c.isAdmin(caller), "caller must not be admin");

        // ensure the caller is actually the sender for the call under test
        // (we cannot change msg.sender, so we must be the caller)
        require(caller == address(this), "caller must be this contract");

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // general rule: for a non-admin caller, the call always reverts
        assert(reverted);
    }

    receive() external payable {}
}
